export const labKey=(band,id)=>band+':'+id;
export const labByKey=new Map(labMissions.map(m=>[labKey(m.band,m.id),m]));
export function normalizeWords(s){return String(s).trim().split(/\s+/).filter(Boolean);}
export function quoteRange(text,phrase){
 const words=normalizeWords(text),needle=normalizeWords(phrase);
 const clean=s=>s.toLowerCase().replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu,'');
 const hits=[];
 for(let i=0;i<=words.length-needle.length;i++)if(needle.every((w,j)=>clean(w)===clean(words[i+j])))hits.push([i,i+needle.length-1]);
 return hits.length===1?hits[0]:null;
}
export function validateLabMissions(){
 const seen=new Set(),types=new Set(['sequence','quote','compare','claim']);
 for(const m of labMissions){
  const key=labKey(m.band,m.id);
  if(seen.has(key)||!Number.isInteger(m.id)||![7,8,9,10,11,12].includes(m.band)||m.id<2||m.id>12||!types.has(m.type)||!m.question||!m.outcome||!m.example)throw Error('Bad authored puzzle '+key);
  seen.add(key);
  if(m.type==='quote'){if(!m.text||!m.phrase||!quoteRange(m.text,m.phrase))throw Error('Missing or ambiguous quote '+key);}
  else{
   if(!Array.isArray(m.cards)||m.cards.length<3||new Set(m.cards).size!==m.cards.length||!Array.isArray(m.solution)||m.solution.length!==m.slots.length||new Set(m.solution).size!==m.solution.length||m.solution.some(i=>!Number.isInteger(i)||i<0||i>=m.cards.length))throw Error('Invalid puzzle board '+key);
   if(m.type==='sequence'&&m.solution.length!==3)throw Error('Sequence needs 3 ordered steps '+key);
   if(m.type==='compare'&&(!Array.isArray(m.sources)||m.sources.length!==2||m.sources.some(s=>!s.label||!s.text)))throw Error('Paired text missing '+key);
   if(m.type==='claim'&&(!m.claim||!m.source))throw Error('Evidence missing '+key);
  }
 }
 return seen.size;
}
validateLabMissions();
